// CSD_RATIONALE_BEGIN
// ROOT CAUSE: Prior attempts used CloseSpanIfComplete at each constrained step,
// closing the span at the FIRST complete parse (e.g., after just "n1 + mult" or
// "n1 + n2 + n3" — only 3-5 tokens). The correct answer is often much longer
// (e.g., "n1 + n1 * mult + n2 + n3" or "first_hour_cost + (end_time - start_time
// - free_hours - 1) * first_hour_cost * multiplier"). Average span length was 4.90
// tokens, producing systematically truncated, wrong expressions.
//
// FIX: Use CloseSpanWithinBudget exclusively for span closure. This helper:
//   - Generates forward for the FULL budget without early stopping
//   - Tracks the LONGEST complete parse seen at any point
//   - Closes at that longest point, not the first
// This lets the model naturally generate the full expression before closure.
//
// STRUCTURE (simplified — no CloseSpanIfComplete calls):
//   Phase 1: UnconstrainedChunk loop, up to 75% budget, watching for "<<"
//   Phase 2: CloseSpanWithinBudget(up to 200 steps) for span found in Phase 1
//   Phase 3: CloseSpanWithinBudget(all remaining) if Phase 2 didn't close
//   Phase 4: OpenConstrainedSpan + CloseSpanWithinBudget(remaining) if no span
//
// Together Phase 2+3 allocate up to (bud2 + rem3) steps — sufficient for any
// arithmetic expression. Phase 4 is the forced-span fallback.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Phase 1 (UnconstrainedChunk loop): insideConstrainedOut stays false until
//     openSeen1. EnterObservedConstrainedSpan sets currentConstrainedOut := []
//     which satisfies parser.IsValidPrefix([]) by the method precondition.
//     When !insideConstrainedOut the implication is vacuously true.
//   Phase 2, 3 (CloseSpanWithinBudget): postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Phase 4 (OpenConstrainedSpan): sets currentConstrainedOut := [] (valid).
//     Nested CloseSpanWithinBudget: same as Phase 2.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: UnconstrainedChunk appends at most stepsUsed non-EOS tokens;
//     EOS uses a step without appending. stepsUsed >= 1 for chunkSz >= 1,
//     so steps strictly increases. Invariant: |cg1| <= |generated| + used1,
//     steps' = steps + used1 => |cg1| <= |generatedPrefix| + steps'.
//     EnterObservedConstrainedSpan: +0 cost, generated unchanged.
//   Phase 2: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated| + bud2.
//     steps' = steps + bud2. So |wg2| <= |generatedPrefix| + steps + bud2 = |generatedPrefix| + steps'.
//   Phase 3: Same as Phase 2 with rem3 = maxSteps - steps => steps' = maxSteps.
//   Phase 4: OpenConstrainedSpan adds 1 token, steps += 1, invariant holds.
//     CloseSpanWithinBudget: same as Phase 2 with rem4 = maxSteps - steps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  return;
}

helpers.AppendTaskGuidance(lm, "Solve step by step. Write: The answer is <<EXPR>> where EXPR is the full arithmetic expression computing the answer. Include ALL terms and factors. Use only variable names, numbers, and +,-,*,/,(,). No LaTeX, no {}, no backslash.");

var steps: nat := 0;
var spanDone: bool := false;

// Phase 1: Unconstrained chunks up to 75% of budget, watching for "<<"
var phaseCap: nat := (maxSteps * 3) / 4;
if phaseCap == 0 {
  phaseCap := maxSteps;
}

while steps < phaseCap && !insideConstrainedOut && !spanDone
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phaseCap - steps
{
  var chunkSz: nat := 50;
  if steps + chunkSz > phaseCap {
    chunkSz := phaseCap - steps;
  }
  if chunkSz == 0 {
    break;
  }
  var cg1, openSeen1, eosSeen1, used1 := helpers.UnconstrainedChunk(lm, prompt, generated, chunkSz, "<<", eosToken);
  generated := cg1;
  steps := steps + used1;
  if eosSeen1 {
    break;
  }
  if openSeen1 {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// Phase 2: Close span with up to 200 steps (CloseSpanWithinBudget tracks LONGEST complete parse)
if insideConstrainedOut && steps < maxSteps {
  var rem2: nat := maxSteps - steps;
  var bud2: nat := rem2;
  if bud2 > 200 {
    bud2 := 200;
  }
  var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2);
  generated := wg2;
  insideConstrainedOut := wi2;
  currentConstrainedOut := wc2;
  steps := steps + bud2;
  if !insideConstrainedOut {
    spanDone := true;
  }
}

// Phase 3: If span still open after Phase 2, use all remaining budget
if insideConstrainedOut && steps < maxSteps {
  var rem3: nat := maxSteps - steps;
  var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem3);
  generated := wg3;
  insideConstrainedOut := wi3;
  currentConstrainedOut := wc3;
  steps := steps + rem3;
  if !insideConstrainedOut {
    spanDone := true;
  }
}

// Phase 4: Force open a span if no span completed yet, close with remaining budget
if !spanDone && !insideConstrainedOut && steps + 1 <= maxSteps {
  var fg4, fi4, fc4 := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg4;
  insideConstrainedOut := fi4;
  currentConstrainedOut := fc4;
  steps := steps + 1;

  if insideConstrainedOut && steps < maxSteps {
    var rem4: nat := maxSteps - steps;
    var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, rem4);
    generated := wg4;
    insideConstrainedOut := wi4;
    currentConstrainedOut := wc4;
    steps := steps + rem4;
  }
}

cost := steps;

